function svg(name,size){var p=ICONS[name];if(!p)return "";size=size||24;var d="";for(var i=1;i<p.length;i++){d+='<path fill="currentColor" d="'+p[i]+'"/>';}return '<svg xmlns="http://www.w3.org/2000/svg" width="'+size+'" height="'+size+'" viewBox="0 '+p[0]+' 960 960" aria-hidden="true">'+d+'</svg>';}
function hydrate(root){var els=(root||document).querySelectorAll("[data-icon]");for(var i=0;i<els.length;i++){var el=els[i];if(el.getAttribute("data-done"))continue;el.innerHTML=svg(el.getAttribute("data-icon"),+el.getAttribute("data-size")||24);el.setAttribute("data-done","1");}}
window.Yabai={icons:Object.keys(ICONS),icon:svg,hydrate:hydrate};
if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",function(){hydrate();});}else{hydrate();}
